package org.agentos.tests;
import android.media.*;
import org.json.*;
import java.io.*;
/** Actual local PCM input/playback initialization; no captured audio is saved or uploaded. */
public final class NativeAudioProbe {
 public static void main(String[] args)throws Exception {android.os.Looper.prepareMainLooper();JSONObject r=new JSONObject();AudioRecord recorder=null;AudioTrack player=null;try{int size=Math.max(19200,AudioRecord.getMinBufferSize(24000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT));recorder=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,24000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,size);if(recorder.getState()!=AudioRecord.STATE_INITIALIZED)throw new IOException("AudioRecord unavailable");recorder.startRecording();byte[] buffer=new byte[4800];int n=recorder.read(buffer,0,buffer.length);r.put("actualPcmInputBytes",n).put("audioInputAvailable",n>0);java.util.Arrays.fill(buffer,(byte)0);player=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ASSISTANT).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(24000).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).setEncoding(AudioFormat.ENCODING_PCM_16BIT).build()).setBufferSizeInBytes(19200).build();r.put("audioPlaybackInitialized",player.getState()==AudioTrack.STATE_INITIALIZED);player.play();player.write(buffer,0,buffer.length);}catch(Exception e){r.put("error",e.getMessage());}finally{if(recorder!=null){try{recorder.stop();}catch(Exception ignored){}recorder.release();}if(player!=null)player.release();}r.put("capturedAudioSavedOrUploaded",false);try(FileOutputStream out=new FileOutputStream("/data/local/tmp/native-audio-acceptance.json")){out.write(r.toString().getBytes("UTF-8"));}System.out.println(r.toString());}
}
